"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4747],{19799:e=>{e.exports=JSON.parse('{"functions":[{"name":"Buy","desc":"Buy one copy of a consumable, or variant `variantIndex` (1-based) of an\\nexpiring perk. Checks the level gate, then deducts coins, then adds the stock;\\na failed deduct changes nothing. Returns (success, reasonCode).","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"id","desc":"","lua_type":"string"},{"name":"variantIndex","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":72,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"Equip","desc":"Equip `id` at the end of `pool` (\\"Personal\\" | \\"Party\\"). The first equip of an\\nexpiring perk starts its clock. Returns (success, reasonCode).","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"id","desc":"","lua_type":"string"},{"name":"pool","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":97,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"Unequip","desc":"Remove the perk at `slotIndex` of `pool`; later slots move up. Does NOT prune\\nfirst, so the index the client sent still points at the perk it shows.\\nReturns (success, reasonCode).","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"pool","desc":"","lua_type":"string"},{"name":"slotIndex","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":119,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"Grant","desc":"Give `amount` copies (consumable) or `amount` seconds (expiring) of `id`, with\\nno price and no level gate (the gate applies at equip). A hidden perk can be\\ngranted; it waits in the inventory. `reason` goes to the server log.\\nReturns (success, reasonCode).","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"id","desc":"","lua_type":"string"},{"name":"amount","desc":"","lua_type":"number"},{"name":"reason","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":138,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"BeginRun","desc":"Start run `runId` for this player (Game Instance only). The first call per run\\nid fixes `ActiveRun` and uses one copy of each equipped consumable; a rejoin\\nkeeps `ActiveRun` and uses nothing. Fires `Signals.OnShopPerksChanged`.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"runId","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":162,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"GetActiveRun","desc":"The shop loadout fixed for this run: `{ Personal = { id }, Party = { id } }`\\n(live reference; read-only by convention). Empty when no profile is loaded.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"{ [string]: { string } }\\n"}],"function_type":"static","source":{"line":177,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"Initialize","desc":"Wire profile lifecycle, replication and the teleport hand-off. Call once per\\nserver, in every place. Pass `runId` in the Game Instance only: each loaded\\nprofile then starts that run, if `isAuthorized(player)` (may yield) allows it.\\nDoes NOT bind the command packets.","params":[{"name":"runId","desc":"","lua_type":"string?"},{"name":"isAuthorized","desc":"","lua_type":"((Player) -> boolean)?"}],"returns":[],"function_type":"static","source":{"line":226,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}},{"name":"WireCommandHandlers","desc":"Bind the buy / equip / unequip request packets. Lobby only. Call once, after\\nInitialize().","params":[],"returns":[],"function_type":"static","source":{"line":273,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}}],"properties":[],"types":[],"name":"PerkInventoryManager","desc":"Authority for shop perks (Perk Rework part 2). Owns the `PlayerPerkInventory`\\nProfileStore (one session per player, key = UserId): `Copies`, `Banked`,\\n`Expires`, `Loadout`, `ConsumedRun`, `ActiveRun`. All rules live in the pure,\\nshared `PerkLoadoutState`. Replicates `PerkInventorySync` to the owner.\\n\\n`Initialize(runId?)` runs in both places. The Game Instance passes the run id:\\neach loaded profile then starts the run (`BeginRun`), which uses the\\nconsumables once per run id. Buy / equip / unequip are bound only by\\n`WireCommandHandlers()`, which only the Lobby calls, so the loadout cannot\\nchange during a run. `Grant` is the no-price, no-level-gate entry point for\\ndrops and the Battle Pass (Perk Rework part 6).","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/PerkInventoryManager.luau"}}')}}]);